#include <bits/stdc++.h>
using namespace std;
const int N=100005,MOD=1e9+7;
int n,m,par_[N],dep[N],comp[N],vis[N],cid,isC[N],up[17][N],cnt[N],d2[N];
vector<int> g[N],t[N];
void dfs(int u,int p){vis[u]=1;for(int v:g[u]){if(v==p)continue;
  if(!vis[v]){par_[v]=u;dep[v]=dep[u]+1;dfs(v,u);}
  else if(dep[v]<dep[u]){int c=++cid;isC[c]=1;for(int w=u;w!=v;w=par_[w])comp[w]=c;comp[v]=c;}}}
int lca(int a,int b){if(d2[a]<d2[b])swap(a,b);for(int k=16;k>=0;k--)if(d2[a]-(1<<k)>=d2[b])a=up[k][a];
  if(a==b)return a;for(int k=16;k>=0;k--)if(up[k][a]!=up[k][b])a=up[k][a],b=up[k][b];return up[0][a];}
int main(){scanf("%d %d",&n,&m);vector<pair<int,int>>E(m);
  for(auto&[a,b]:E){scanf("%d %d",&a,&b);g[a].push_back(b);g[b].push_back(a);}
  dfs(1,0);for(int v=1;v<=n;v++)if(!comp[v])comp[v]=++cid;
  for(auto[a,b]:E)if(comp[a]!=comp[b]){t[comp[a]].push_back(comp[b]);t[comp[b]].push_back(comp[a]);}
  vector<int>q={comp[1]};vector<int>seen(cid+1,0);seen[comp[1]]=1;up[0][comp[1]]=comp[1];cnt[comp[1]]=isC[comp[1]];
  for(size_t i=0;i<q.size();i++){int u=q[i];for(int v:t[u])if(!seen[v]){seen[v]=1;up[0][v]=u;d2[v]=d2[u]+1;cnt[v]=cnt[u]+isC[v];q.push_back(v);}}
  for(int k=1;k<17;k++)for(int v=1;v<=cid;v++)up[k][v]=up[k-1][up[k-1][v]];
  vector<long long>p2(n+1,1);for(int i=1;i<=n;i++)p2[i]=p2[i-1]*2%MOD;
  int k;scanf("%d",&k);while(k--){int x,y;scanf("%d %d",&x,&y);int a=comp[x],b=comp[y],l=lca(a,b);
    printf("%lld\n",p2[cnt[a]+cnt[b]-2*cnt[l]+isC[l]]);}}

