using namespace std;typedef long long ll;typedef pair<ll,ll> P;
ll d(P a,P b){return llabs(a.first-b.first)+llabs(a.second-b.second);}
int main(){int n;scanf("%d",&n);map<ll,vector<P>>lv;
  for(int i=0;i<n;i++){ll x,y;scanf("%lld %lld",&x,&y);lv[max(x,y)].push_back({x,-y});}
  P e0={0,0},e1={0,0};ll d0=0,d1=0;
  for(auto&[L,v]:lv){sort(v.begin(),v.end());for(auto&p:v)p.second=-p.second;
    P a=v.front(),b=v.back();ll w=d(a,b);
    ll n0=min(d0+d(e0,b),d1+d(e1,b))+w; // end at a
    ll n1=min(d0+d(e0,a),d1+d(e1,a))+w; // end at b
    d0=n0;d1=n1;e0=a;e1=b;}
  printf("%lld\n",min(d0,d1));}

