int main(){int t;scanf("%d",&t);while(t--){int n;ll x;scanf("%d %lld",&n,&x);
  vector<vector<ll>>a(n),b(n);vector<int>pos(n,0);
  // heap of next profitable block per building: (requirement, building, end index)
  priority_queue<tuple<ll,int,int>,vector<tuple<ll,int,int>>,greater<>>pq;
  auto push=[&](int i){ll s=0,req=0;for(int j=pos[i];j<(int)a[i].size();j++){
      req=max(req,a[i][j]-s);s+=b[i][j]-a[i][j];if(s>0){pq.push({req,i,j+1});return;}}};
  for(int i=0;i<n;i++){int m;scanf("%d",&m);a[i].resize(m);b[i].resize(m);
    for(auto&v:a[i])scanf("%lld",&v);for(auto&v:b[i])scanf("%lld",&v);push(i);}
  while(!pq.empty()){auto[req,i,e]=pq.top();if(req>x)break;pq.pop();
    for(int j=pos[i];j<e;j++)x+=b[i][j]-a[i][j];pos[i]=e;push(i);}
  int best=-1,id=0;for(int i=0;i<n;i++){ll y=x;int h=pos[i];
    while(h<(int)a[i].size()&&y>=a[i][h]){y+=b[i][h]-a[i][h];h++;}
    if(h>best){best=h;id=i+1;}}
  printf("%d %d\n",best,id);}}

