bool lucky(ll v){while(v){if(v%10!=4&&v%10!=7)return false;v/=10;}return true;}
int main(){int n,k;scanf("%d %d",&n,&k);map<ll,ll>cnt;ll U=0;
  for(int i=0;i<n;i++){ll v;scanf("%lld",&v);if(lucky(v))cnt[v]++;else U++;}
  vector<ll>dp(cnt.size()+1,0);dp[0]=1;int L=0;
  for(auto&[v,c]:cnt){L++;for(int j=L;j>=1;j--)dp[j]=(dp[j]+dp[j-1]*c)%M;}
  vector<ll>f(n+1,1);for(int i=1;i<=n;i++)f[i]=f[i-1]*i%M;
  auto C=[&](ll a,ll b)->ll{if(b<0||b>a)return 0;return f[a]*pw(f[b]*f[a-b],M-2)%M;};
  ll ans=0;for(int j=0;j<=L&&j<=k;j++)ans=(ans+dp[j]*C(U,k-j))%M;
  printf("%lld\n",ans);}

