#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll M=1e9+7;
// count a>=1 with b=2(a&~b) (bitwise), a<b, c=a^b<=n
ll solve(ll n){ // state: bprev bit b_i, cmpAB (0 eq,1 a<b,2 a>b), cmpCN (0 eq,1 c<n,2 c>n), aNonzero
  ll dp[2][3][3][2]={};dp[0][0][0][0]=1;
  for(int i=0;i<=62;i++){ll nd[2][3][3][2]={};int nb=(n>>i)&1;
    for(int bi=0;bi<2;bi++)for(int x=0;x<3;x++)for(int y=0;y<3;y++)for(int z=0;z<2;z++)if(dp[bi][x][y][z])
      for(int ai=0;ai<=(i<=60);ai++){int ci=ai^bi,bn=ai&!bi;
        int X=ai<bi?1:ai>bi?2:x,Y=ci<nb?1:ci>nb?2:y;
        ll &r=nd[bn][X][Y][z|ai];r=(r+dp[bi][x][y][z])%M;}
    memcpy(dp,nd,sizeof dp);}
  ll s=0;for(int y=0;y<2;y++)s=(s+dp[0][1][y][1])%M;return s;}
int main(){int t;scanf("%d",&t);while(t--){ll n;scanf("%lld",&n);printf("%lld\n",solve(n));}}

