int main(){int n,k;cin>>n>>k;int A=0,B=0;for(int i=0;i<n;i++){int w;cin>>w;(w==50?A:B)++;}
  ll C[51][51]={};for(int i=0;i<=50;i++){C[i][0]=1;for(int j=1;j<=i;j++)C[i][j]=(C[i-1][j-1]+C[i-1][j])%M;}
  // state (fifties on left, hundreds on left, boat side 0=left)
  vector<int>dist(52*52*2,-1);vector<ll>ways(52*52*2,0);auto id=[](int a,int b,int s){return (a*52+b)*2+s;};
  queue<array<int,3>>q;q.push({A,B,0});dist[id(A,B,0)]=0;ways[id(A,B,0)]=1;
  while(!q.empty()){auto[a,b,s]=q.front();q.pop();int cur=id(a,b,s);
    int ha=s?A-a:a,hb=s?B-b:b; // people on the boat's side
    for(int i=0;i<=ha;i++)for(int j=0;j<=hb;j++){if(i+j==0||50*i+100*j>k)continue;
      int na=s?a+i:a-i,nb=s?b+j:b-j,nx=id(na,nb,!s);ll w=ways[cur]*C[ha][i]%M*C[hb][j]%M;
      if(dist[nx]==-1){dist[nx]=dist[cur]+1;q.push({na,nb,!s});}
      if(dist[nx]==dist[cur]+1)ways[nx]=(ways[nx]+w)%M;}}
  int t=id(0,0,1);if(dist[t]<0)cout<<"-1\n0\n";else cout<<dist[t]<<"\n"<<ways[t]<<"\n";}

