// best packing of intervals strictly inside [lo,hi] excluding self; returns h array
vector<int> pack(int lo,int hi,int self){vector<int>h(hi-lo+1,0);
  for(int x=lo+1;x<=hi;x++){h[x-lo]=h[x-lo-1];for(int j:endAt[x])if(j!=self&&L[j]>=lo)h[x-lo]=max(h[x-lo],h[L[j]-lo]+f[j]);}
  return h;}
