  while(x>lo){if(h[x-lo]==h[x-lo-1]){x--;continue;}
    for(int j:endAt[x])if(j!=self&&L[j]>=lo&&h[L[j]-lo]+f[j]==h[x-lo]){out.push_back(j);collect(L[j],R[j],j,out);x=L[j];break;}}}
