  sort(xs.begin(),xs.end());xs.erase(unique(xs.begin(),xs.end()),xs.end());X=xs.size();endAt.assign(X,{});
  for(int i=0;i<n;i++){L[i]=lower_bound(xs.begin(),xs.end(),L[i])-xs.begin();R[i]=lower_bound(xs.begin(),xs.end(),R[i])-xs.begin();endAt[R[i]].push_back(i);}
  vector<int>o(n);iota(o.begin(),o.end(),0);sort(o.begin(),o.end(),[&](int a,int b){return R[a]-L[a]<R[b]-L[b];});
