using namespace std;typedef pair<int,int> P; // (dp value, row)
int K;vector<P>t,lz;
void app(int x,P v){t[x]=max(t[x],v);lz[x]=max(lz[x],v);}
void upd(int x,int l,int r,int ql,int qr,P v){if(qr<l||r<ql)return;if(ql<=l&&r<=qr){app(x,v);return;}
  app(2*x,lz[x]);app(2*x+1,lz[x]);int m=(l+r)/2;upd(2*x,l,m,ql,qr,v);upd(2*x+1,m+1,r,ql,qr,v);t[x]=max(t[2*x],t[2*x+1]);}
P qry(int x,int l,int r,int ql,int qr){if(qr<l||r<ql)return {0,0};if(ql<=l&&r<=qr)return t[x];
  app(2*x,lz[x]);app(2*x+1,lz[x]);int m=(l+r)/2;return max(qry(2*x,l,m,ql,qr),qry(2*x+1,m+1,r,ql,qr));}
