using namespace std;typedef long long ll;const ll M=1e9+7;
int n;struct BIT{vector<ll>t;void init(int s){t.assign(s+2,0);}void add(int i,ll v){for(i++;i<(int)t.size();i+=i&-i)t[i]=(t[i]+v)%M;}
  ll sum(int i){ll r=0;for(i++;i>0;i-=i&-i)r+=t[i];return r%M;}};
int main(){int T;scanf("%d",&T);while(T--){scanf("%d",&n);vector<int>a(n);for(auto&x:a)scanf("%d",&x);
  // state (A = max so far, B = max "inverted" element); row[A] is a BIT over B, col[B] a BIT over A
  vector<BIT>row(n+1),col(n+1);for(int i=0;i<=n;i++){row[i].init(n+1);col[i].init(n+1);}
  row[0].add(0,1);col[0].add(0,1);ll total=1;
  for(int x:a){vector<pair<pair<int,int>,ll>>add;
    for(int b=0;b<=x;b++){ll s=col[b].sum(x);if(s)add.push_back({{x,b},s});}       // A<=x, B=b<=x -> (x,b)
    for(int A=x+1;A<=n;A++){ll s=row[A].sum(x);if(s)add.push_back({{A,x},s});}      // A>x, B<=x -> (A,x)
    for(auto&[k,v]:add){row[k.first].add(k.second,v);col[k.second].add(k.first,v);total=(total+v)%M;}}
  printf("%lld\n",total);}}

