using namespace std;typedef long long ll;const ll M=998244353;
int main(){int n;cin>>n;vector<ll>v(n,-1);for(int i=0;i<n;i++){char c;cin>>c;if(c=='+')cin>>v[i];}
  ll ans=0;
  for(int i=0;i<n;i++)if(v[i]>=0){vector<ll>dp(n+1,0);dp[0]=1;
    auto smaller=[&](int j){return v[j]<v[i]||(v[j]==v[i]&&j<i);};
    for(int j=0;j<n;j++){if(j==i)continue;vector<ll>nd(dp);
      if(v[j]<0){for(int c=0;c<=n;c++)if(dp[c]){if(c>0)nd[c-1]=(nd[c-1]+dp[c])%M;else if(j<i)nd[0]=(nd[0]+dp[0])%M;}}
      else if(smaller(j)){for(int c=0;c<n;c++)if(dp[c])nd[c+1]=(nd[c+1]+dp[c])%M;}
      else for(int c=0;c<=n;c++)nd[c]=dp[c]*2%M;
      dp=nd;}
    ll ways=0;for(ll x:dp)ways=(ways+x)%M;ans=(ans+ways*(v[i]%M))%M;}
  cout<<ans<<endl;}

