using namespace std;
bool lessNum(const string&a,const string&b){return a.size()!=b.size()?a.size()<b.size():a<b;}
string minWithSum(int s){ // smallest number (no leading zero, may be "0") with digit sum s and last digit != 9
  if(s<0)return "";int last=min(8,s);s-=last;string r;while(s>0){int d=min(9,s);r=char('0'+d)+r;s-=d;}
  return (r+char('0'+last));}
int main(){int t;cin>>t;while(t--){int n,k;cin>>n>>k;string best="";
  for(int c=0;c<=17;c++)for(int d=0;d<=9;d++){ // x = P, then c nines, then digit d
    int cst=0;for(int i=0;i<=k;i++)cst+=(d+i<=9)?9*c+d+i:d+i-10+1; // digit sum of x+i minus f(P)
    int rem=n-cst;if(rem<0||rem%(k+1))continue;int sP=rem/(k+1);
    string P=minWithSum(sP);if(P.empty())continue;
    string x=P+string(c,'9')+char('0'+d);size_t p=x.find_first_not_of('0');x=p==string::npos?"0":x.substr(p);
    if(best.empty()||lessNum(x,best))best=x;}
  cout<<(best.empty()?"-1":best)<<"\n";}}

