int n,k;vector<int>w;vector<vector<int>>g,dp;
void dfs(int v,int p){dp[v].assign(n+1,0);vector<int>ch;for(int c:g[v])if(c!=p){dfs(c,v);ch.push_back(c);}
  dp[v][0]=w[v];for(int c:ch)dp[v][0]+=dp[c][k];
  for(int d=1;d<=n;d++){for(int c:ch){int val=dp[c][d-1];for(int o:ch)if(o!=c)val+=dp[o][max(d-1,k-d)];dp[v][d]=max(dp[v][d],val);}}
  for(int d=n-1;d>=0;d--)dp[v][d]=max(dp[v][d],dp[v][d+1]);}
