using namespace std;typedef long long ll;const ll INF=LLONG_MAX/4;
int main(){int t;scanf("%d",&t);while(t--){int n,m,k;scanf("%d %d %d",&n,&m,&k);vector<ll>x(n+1);for(int i=1;i<=n;i++)scanf("%lld",&x[i]);
  // points per floor: (col, id); ladder from point id -> point id2 with gain h
  vector<vector<pair<int,int>>>fl(n+1);vector<ll>dp;vector<vector<pair<int,ll>>>out;
  auto np=[&](int f,int c){fl[f].push_back({c,(int)dp.size()});dp.push_back(INF);out.push_back({});return (int)dp.size()-1;};
  int s=np(1,1),e=np(n,m);
  for(int i=0;i<k;i++){int a,b,c,d;ll h;scanf("%d %d %d %d %lld",&a,&b,&c,&d,&h);int p=np(a,b),q=np(c,d);out[p].push_back({q,h});}
  dp[s]=0;
  for(int f=1;f<=n;f++){auto&v=fl[f];sort(v.begin(),v.end());
    for(size_t i=1;i<v.size();i++)if(dp[v[i-1].second]<INF)dp[v[i].second]=min(dp[v[i].second],dp[v[i-1].second]+(v[i].first-v[i-1].first)*x[f]);
    for(int i=(int)v.size()-2;i>=0;i--)if(dp[v[i+1].second]<INF)dp[v[i].second]=min(dp[v[i].second],dp[v[i+1].second]+(v[i+1].first-v[i].first)*x[f]);
    for(auto&[c,id]:v)if(dp[id]<INF)for(auto[q,h]:out[id])dp[q]=min(dp[q],dp[id]-h);}
  if(dp[e]>=INF)puts("NO ESCAPE");else printf("%lld\n",dp[e]);}}

