int main(){int n;cin>>n;vector<vector<double>>p(n,vector<double>(n));for(auto&r:p)for(auto&x:r)cin>>x;
  if(n==1){printf("%.10f\n",1.0);return 0;}
  int F=1<<n;vector<vector<double>>dp(F,vector<double>(n,0)); // dp[mask][i]: mask = already fought, i = current champion
  dp[F-1][0]=1;
  for(int mask=F-2;mask>0;mask--)for(int i=0;i<n;i++)if(mask>>i&1){double b=0;
    for(int j=0;j<n;j++)if(!(mask>>j&1)){int nm=mask|1<<j;b=max(b,p[i][j]*dp[nm][i]+p[j][i]*dp[nm][j]);}dp[mask][i]=b;}
  double ans=0;for(int i=0;i<n;i++)ans=max(ans,dp[1<<i][i]);printf("%.10f\n",ans);}

#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll M=998244353;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<ll>a(n);for(auto&x:a)scanf("%lld",&x);
  vector<ll>p2(n+1,1);for(int i=1;i<=n;i++)p2[i]=p2[i-1]*2%M;
  auto calc=[&](vector<ll>v){ // f[i]: ways for prefix records ending exactly at i (a_i is a record of the same set)
    vector<ll>L;ll mx=0;for(ll x:v)if(x>mx){L.push_back(x);mx=x;}map<ll,int>rk;for(size_t i=0;i<L.size();i++)rk[L[i]]=i;
    vector<ll>f(n,0);for(int i=0;i<n;i++)if(v[i]==L[0])f[i]=1;
    for(int j=0;j<n;j++){if(!f[j]||!rk.count(v[j])||rk[v[j]]+1>=(int)L.size())continue;ll nxt=L[rk[v[j]]+1];int c=0;
      for(int i=j+1;i<n;i++){if(v[i]==nxt)f[i]=(f[i]+f[j]*p2[c])%M;if(v[i]<=v[j])c++;}}
    return f;};
  vector<ll>f=calc(a),ra(a.rbegin(),a.rend()),gr=calc(ra),g(n);for(int i=0;i<n;i++)g[i]=gr[n-1-i];
  ll Mx=*max_element(a.begin(),a.end()),ans=0;
  for(int i=0;i<n;i++)if(a[i]==Mx&&f[i])for(int j=i;j<n;j++)if(a[j]==Mx&&g[j])ans=(ans+f[i]*g[j]%M*(i==j?1:p2[j-i-1]))%M;
  printf("%lld\n",ans);}}

