#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll M=998244353;
int main(){int n,m;scanf("%d %d",&n,&m);vector<int>l(n),r(n);for(int i=0;i<n;i++)scanf("%d %d",&l[i],&r[i]);
  vector<int>mu(m+1,0);mu[1]=1;for(int i=1;i<=m;i++)for(int j=2*i;j<=m;j+=i)mu[j]-=mu[i];
  ll ans=0;
  for(int d=1;d<=m;d++){if(!mu[d])continue;int S=m/d;vector<ll>dp(S+1,0),nd(S+1),pre(S+2);dp[0]=1;bool ok=true;
    for(int i=0;i<n&&ok;i++){int lo=(l[i]+d-1)/d,hi=r[i]/d;if(lo>hi){ok=false;break;}
      pre[0]=0;for(int s=0;s<=S;s++)pre[s+1]=(pre[s]+dp[s])%M;
      for(int s=0;s<=S;s++){int a=s-hi,b=s-lo;if(b<0){nd[s]=0;continue;}a=max(a,0);nd[s]=(pre[b+1]-pre[a]+M)%M;}
      swap(dp,nd);}
    if(!ok)continue;ll tot=0;for(ll x:dp)tot=(tot+x)%M;ans=(ans+mu[d]*tot%M+M)%M;}
  printf("%lld\n",ans);}

