int main(){int n;scanf("%d",&n);vector<int>a(n);for(auto&x:a)scanf("%d",&x);vector<int>f(n),g(n),t;
  for(int i=0;i<n;i++){auto it=lower_bound(t.begin(),t.end(),a[i]);f[i]=it-t.begin()+1;if(it==t.end())t.push_back(a[i]);else *it=a[i];}
  t.clear();for(int i=n-1;i>=0;i--){int v=-a[i];auto it=lower_bound(t.begin(),t.end(),v);g[i]=it-t.begin()+1;if(it==t.end())t.push_back(v);else *it=v;}
  int L=0;for(int i=0;i<n;i++)L=max(L,f[i]);vector<int>cnt(n+2,0);
  for(int i=0;i<n;i++)if(f[i]+g[i]-1==L)cnt[f[i]]++;
  string r(n,'1');for(int i=0;i<n;i++)if(f[i]+g[i]-1==L)r[i]=cnt[f[i]]==1?'3':'2';puts(r.c_str());}

#include <bits/stdc++.h>
using namespace std;
vector<int> uniq(const string&s){int n=s.size();vector<int>u(n,0),nx(n+1,0),cur(n+1,0); // u[i] = 1 + max lcp(s[i..], s[j..]), j != i
  for(int i=n-1;i>=0;i--){for(int j=n-1;j>=0;j--){cur[j]=(s[i]==s[j])?nx[j+1]+1:0;if(j!=i)u[i]=max(u[i],cur[j]);}swap(nx,cur);}
  for(int i=0;i<n;i++)u[i]++;return u;}
int main(){string a,b;cin>>a>>b;int n=a.size(),m=b.size();auto ua=uniq(a),ub=uniq(b);int best=INT_MAX;
  vector<int>nx(m+1,0),cur(m+1,0);
  for(int i=n-1;i>=0;i--){for(int j=m-1;j>=0;j--){cur[j]=(a[i]==b[j])?nx[j+1]+1:0;int need=max(ua[i],ub[j]);if(need<=cur[j])best=min(best,need);}swap(nx,cur);}
  printf("%d\n",best==INT_MAX?-1:best);}

#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll M=1e9+7;
ll pw(ll b,ll e){ll r=1;b%=M;for(;e;e>>=1,b=b*b%M)if(e&1)r=r*b%M;return r;}
int main(){int k;ll pa,pb;cin>>k>>pa>>pb;ll inv=pw(pa+pb,M-2),A=pa*inv%M,B=pb*inv%M,ab=pa*pw(pb,M-2)%M;
  vector<vector<ll>>dp(k+1,vector<ll>(k+1,0)); // dp[i][j]: i a's, j ab's, expected final ab count
  for(int i=k;i>=1;i--)for(int j=k-1;j>=0;j--){
    if(i+j>=k)dp[i][j]=(i+j+ab)%M;
    else dp[i][j]=(A*dp[i+1][j]+B*dp[i][j+i])%M;}
  cout<<dp[1][0]<<endl;}

