const int B=19;
int main(){int n,q;scanf("%d %d",&n,&q);vector<int>a(n);for(auto&x:a)scanf("%d",&x);
  vector<array<int,B>>go(n+1);array<int,B>last;last.fill(n);for(int b=0;b<B;b++)go[n][b]=n;
  for(int i=n-1;i>=0;i--){for(int b=0;b<B;b++)go[i][b]=n;
    for(int c=0;c<B;c++)if(a[i]>>c&1){go[i][c]=i;int j=last[c];if(j<n)for(int b=0;b<B;b++)go[i][b]=min(go[i][b],go[j][b]);}
    for(int c=0;c<B;c++)if(a[i]>>c&1)last[c]=i;}
  while(q--){int x,y;scanf("%d %d",&x,&y);x--;y--;bool ok=false;for(int b=0;b<B;b++)if((a[y]>>b&1)&&go[x][b]<=y)ok=true;puts(ok?"Shi":"Fou");}}

#include <bits/stdc++.h>
using namespace std;
int main(){static char buf[1000005];scanf("%s",buf);string s(buf);int n=s.size();
  vector<int>pi(n+11,0);vector<array<int,26>>aut(n); // aut[k][c]: next prefix length from state k (k<n)
  for(int i=1;i<n;i++){int k=pi[i-1];while(k&&s[i]!=s[k])k=pi[k-1];if(s[i]==s[k])k++;pi[i]=k;}
  for(int k=0;k<n;k++)for(int c=0;c<26;c++){if(s[k]-'a'==c)aut[k][c]=k+1;else aut[k][c]=k?aut[pi[k-1]][c]:0;}
  int q;scanf("%d",&q);string full=s;
  while(q--){scanf("%s",buf);string t(buf);full.resize(n);full+=t;
    for(int i=n;i<n+(int)t.size();i++){int k=pi[i-1];int c=full[i]-'a';
      while(k>=n){if(full[k]==full[i])break;k=pi[k-1];}
      if(k>=n)k=k+1;else k=(k<n)?aut[k][c]:0;pi[i]=k;printf("%d ",k);}
    puts("");}}
